import { useState } from 'react'
import { APP_REGISTRY } from '@/app/config/appRegistry'
import { AppMarketplaceCard } from '@/shared/ui/AppMarketplaceCard'
import { useTenant } from '@/app/providers/TenantProvider'
import { toast } from 'sonner'

export function AppsMarketplacePage() {
  const { manifest } = useTenant()
  const [search, setSearch] = useState('')

  const filtered = APP_REGISTRY.filter((app) =>
    app.label.toLowerCase().includes(search.toLowerCase()) ||
    app.description.toLowerCase().includes(search.toLowerCase()),
  )

  const enabledApps = manifest?.enabledApps ?? []

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-5xl mx-auto">
        <div className="mb-6">
          <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search apps..."
            className="w-full max-w-sm rounded-lg border border-border bg-background px-3 py-2 text-sm outline-none focus:border-accent" />
        </div>
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {filtered.map((app) => (
            <AppMarketplaceCard key={app.id} app={app} enabled={enabledApps.includes(app.id)}
              onEnable={() => toast.success(`${app.label} enabled`)}
              onDisable={() => toast.info(`${app.label} disabled`)}
              onOpen={() => toast.info(`Opening ${app.label}...`)} />
          ))}
        </div>
      </div>
    </div>
  )
}
